template:
% 参数由系统自动注入：\def\len{4} \def\wid{3} \def\hgt{3}
% 视觉归一化：把长(len)缩放到 6（单位由 coordScale 决定），保证图形视觉大小稳定；
% 只缩放坐标，线宽、字体、虚线样式保持不变。
\pgfmathsetmacro{\figscale}{6 / \len}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  % 斜二测：y 轴与 x 轴夹角 45 度、长度取一半
  \pgfmathsetmacro\yd{\wid/2}
  \pgfmathsetmacro\ys{\yd*cos(45)}
  \pgfmathsetmacro\zs{\yd*sin(45)}
  % 底面 ABCD（A 原点，AB 沿 x，AD 沿 45 度斜向）
  \coordinate (A) at (0,0);
  \coordinate (B) at (\len,0);
  \coordinate (D) at (\ys,\zs);
  \pgfmathsetmacro\bx{\len+\ys}
  \coordinate (C) at (\bx,\zs);
  % 顶面 A1B1C1D1 平移高 hgt
  \coordinate (A1) at (0,\hgt);
  \coordinate (B1) at (\len,\hgt);
  \coordinate (C1) at (\bx,\hgt+\zs);
  \coordinate (D1) at (\ys,\hgt+\zs);
  % 可见棱：前面 AB、BC 与三条竖棱 A A1、B B1、C C1 实线
  \draw[thick] (A) -- (B) -- (C) -- (C1) -- (B1) -- (A1) -- cycle;
  \draw[thick] (B) -- (B1);
  % 被遮挡棱：AD、DC、DD1 虚线
  \draw[thick, dashed] (A) -- (D) -- (C);
  \draw[thick, dashed] (D) -- (D1);
  % 顶点标签放外轮廓外侧
  \node[below left=3pt] at (A) {$A$};
  \node[below=3pt] at (B) {$B$};
  \node[right=3pt] at (C) {$C$};
  \node[above left=3pt] at (D) {$D$};
  \node[left=3pt] at (A1) {$A_1$};
  \node[above=3pt] at (B1) {$B_1$};
  \node[above right=3pt] at (C1) {$C_1$};
  \node[right=3pt] at (D1) {$D_1$};
\end{tikzpicture}
